//! New CODA carrier-manifest v2 hashing fixture shared with the Python test.
//!
//! Both readers use `engine/tests/golden/carrier_manifest_v2.json`.
//! The original upstream golden bytes remain `OPEN_UNAVAILABLE_GOLDEN`.
//! This fixture was authored for CODA and its expectations generated by the
//! existing Python encoder; this test independently recomputes them in Rust.
//! See `engine/tests/golden/README.md` for source custody and scope.
//!
//! Tests only assert. An intentional fixture change requires explicit generation:
//! `python engine/tests/golden/regenerate_carrier_manifest_v2.py --write`
//! followed by both Python and Rust checks. No environment variable can cause
//! this test to rewrite expectations during validation.
//!
//! Raw rational pairs, dimensions, and provenance strings make this a finite
//! hashing check independent of graph-carrier construction in either language.

use num_bigint::BigInt;
use num_rational::BigRational;
use core_homology::carrier_manifest::{COEFFICIENT_DOMAIN, COEFFICIENT_REPRESENTATION};
use core_homology::hashing::{
    hash_carrier_manifest, hash_cochain_witness, hash_matrix, hash_provenance, hash_weights,
    Hash256,
};
use core_homology::scalar::{hash_rational, Q};
use serde_json::{json, Value};
use std::path::PathBuf;

fn golden_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../tests/core_homology/fixtures/carrier_manifest_v2.json")
}

fn q(pair: &Value) -> Q {
    let n = pair[0].as_str().expect("numerator is a decimal string");
    let d = pair[1].as_str().expect("denominator is a decimal string");
    BigRational::new(
        n.parse::<BigInt>().expect("numerator parses"),
        d.parse::<BigInt>().expect("denominator parses"),
    )
}

fn rationals(v: &Value) -> Vec<Q> {
    v.as_array().expect("array").iter().map(q).collect()
}

fn matrix(v: &Value) -> linear_algebra::backend::basic_matrix::BasicMatrix<Q> {
    let rows = v["rows"].as_u64().expect("rows") as usize;
    let cols = v["cols"].as_u64().expect("cols") as usize;
    let data = rationals(&v["data"]);
    assert_eq!(data.len(), rows * cols, "fixture matrix is not rows*cols");
    linear_algebra::backend::basic_matrix::BasicMatrix::from_row_major(rows, cols, data)
        .expect("fixture matrix is well formed")
}

/// Hash a single rational exactly as the manifest path does.
fn rational_digest(value: &Q) -> Hash256 {
    let mut h = blake3::Hasher::new();
    hash_rational(&mut h, value);
    Hash256(*h.finalize().as_bytes())
}

/// Compute every digest the fixture pins, from its raw inputs.
fn compute(fixture: &Value) -> Value {
    let rational_digests: Vec<String> = rationals(&fixture["inputs"]["rationals"])
        .iter()
        .map(|r| rational_digest(r).to_hex())
        .collect();

    let d0 = matrix(&fixture["inputs"]["d0"]);
    let d1 = matrix(&fixture["inputs"]["d1"]);
    let weights = rationals(&fixture["inputs"]["weights"]);
    let source = fixture["inputs"]["provenance"]
        .as_str()
        .expect("provenance string");

    let d0_hash = hash_matrix(&d0);
    let d1_hash = hash_matrix(&d1);
    let weights_hash = hash_weights(&weights);
    let provenance_hash = hash_provenance(source);
    let witness_hash = hash_cochain_witness(
        (d0.rows(), d0.cols()),
        (d1.rows(), d1.cols()),
        &provenance_hash,
    );
    let (c0, c1, c2) = (
        fixture["inputs"]["c0_dim"].as_u64().expect("c0") as usize,
        fixture["inputs"]["c1_dim"].as_u64().expect("c1") as usize,
        fixture["inputs"]["c2_dim"].as_u64().expect("c2") as usize,
    );
    let carrier_hash = hash_carrier_manifest(c0, c1, c2, &d0_hash, &d1_hash, &weights_hash);

    json!({
        "rationals": rational_digests,
        "d0_hash": d0_hash.to_hex(),
        "d1_hash": d1_hash.to_hex(),
        "weights_hash": weights_hash.to_hex(),
        "provenance_hash": provenance_hash.to_hex(),
        "witness_hash": witness_hash.to_hex(),
        "carrier_hash": carrier_hash.to_hex(),
        "coefficient_domain": COEFFICIENT_DOMAIN,
        "coefficient_representation": COEFFICIENT_REPRESENTATION,
    })
}

#[test]
fn golden_vectors_match_and_are_shared_with_the_python_rail() {
    let path = golden_path();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read the shared fixture at {}: {e}", path.display()));
    let fixture: Value = serde_json::from_str(&text).expect("fixture is valid JSON");

    let computed = compute(&fixture);

    assert_eq!(
        fixture["expected"], computed,
        "carrier-manifest v2 digests drifted from the shared fixture. \
         Review the encoder change, regenerate explicitly if intended, and replay both tests."
    );
}

/// The fixture must contain the pair whose *unframed* limbs collide, or the
/// framing it pins is not actually being exercised.
#[test]
fn the_fixture_exercises_the_variable_width_limb_collision() {
    let text = std::fs::read_to_string(golden_path()).expect("fixture readable");
    let fixture: Value = serde_json::from_str(&text).expect("valid JSON");
    let rats = rationals(&fixture["inputs"]["rationals"]);

    let unframed = |v: &Q| {
        let mut out = v.numer().to_signed_bytes_le();
        out.extend_from_slice(&v.denom().to_signed_bytes_le());
        out
    };
    let a = BigRational::new(BigInt::from(1), BigInt::from(515));
    let b = BigRational::new(BigInt::from(769), BigInt::from(2));
    assert_eq!(
        unframed(&a),
        unframed(&b),
        "premise: this pair must collide"
    );

    assert!(
        rats.contains(&a) && rats.contains(&b),
        "the fixture must include 1/515 and 769/2 — without them a Python \
         implementation that forgot the length prefixes would still pass"
    );
}

